env.CMUX_UI_TEST_SOCKET_COMMANDS:
new_workspace api server
select_workspace {last}
wait 500
let api
set_agent_pid claude_code {pid} --tab={api}
set_agent_lifecycle claude_code running --tab={api}
set_status claude_code "Running subagents" --icon=point.3.filled.connected.trianglepath.dotted --color=#4C8DFF --work=subagents --tab={api}
report_git_branch feat/fan-out --status=dirty --tab={api}
wait 400
new_workspace release gate
select_workspace {last}
wait 500
let gate
set_agent_pid claude_code {pid} --tab={gate}
set_agent_lifecycle claude_code running --tab={gate}
set_status claude_code Waiting --icon=hourglass --color=#8E8E93 --work=waiting --tab={gate}
report_git_branch feat/release-gate --status=clean --tab={gate}
wait 400
new_workspace worker
select_workspace {last}
wait 500
let worker
set_agent_pid codex {pid} --tab={worker}
set_agent_lifecycle codex running --tab={worker}
set_status codex Running --icon=bolt.fill --color=#4C8DFF --work=running --tab={worker}
report_git_branch feat/worker-queue --status=clean --tab={worker}
wait 400
new_workspace review
select_workspace {last}
wait 500
let review
set_agent_pid claude_code {pid} --tab={review}
set_agent_lifecycle claude_code needsInput --tab={review}
set_status claude_code "Needs input" --icon=bell.fill --color=#4C8DFF --tab={review}
wait 400
new_workspace docs
select_workspace {last}
wait 500
let docs
set_agent_lifecycle claude_code idle --tab={docs}
report_git_branch docs/configuration --tab={docs}
report_pr 15164 https://github.com/manaflow-ai/cmux/pull/15164 --label=PR --state=merged --tab={docs}
wait 400
select_workspace {api}
wait 600
